/**
 * Type-only declaration for the `@canopy/brand/current` runtime module.
 *
 * At BUILD/RUNTIME, bundler aliases (Vite, esbuild, Next webpack, jest
 * moduleNameMapper) resolve this module to `.cache/brand/current/desktop-brand.ts`,
 * which is regenerated by `scripts/brand/prepare-brand.mjs`.
 *
 * At TYPE-CHECK time, this `.d.ts` is what `@canopy/brand/current` resolves to.
 * Keeping the type-side resolution inside the protocol package's `rootDir`
 * lets composite TS projects compile without pulling the generated cache
 * file into their file set.
 *
 * The implementer (`prepare-brand.mjs`) MUST emit a module whose runtime
 * shape matches {@link DesktopBrandRuntime} exactly.
 */
import type { DesktopBrandRuntime } from './brand';

export const BRAND: DesktopBrandRuntime;
declare const _default: DesktopBrandRuntime;
export default _default;
